tura_card":false,"s22ac06_datos_crudos_a_lf":true,"s22ac06_campo_controlado_por_lf":true,"s22ac06_branding_o_logo_no_autorizado":true,"s22ac06_estado_visual_o_cta_invalido":true,"s22ac06_produccion_sin_binding":true,"s22ac06_artefacto_no_permitido":true},"esperado":false}]},"hash":"f1573f5f70f92582c364c63bf1848ce3940ab872ec2805baa648b2771c834dd8","hash_paquete":"2cb379ab1a4405ba5208fb9283a0eb2158743dd69881dd4ef2801bd3c795ac0e","hash_evaluado":"f1573f5f70","hash_paquete_10":"2cb379ab1a","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22AC-C07","legacy_id":13124,"legacy_ids":[13124],"relacionadas":[],"residual":"","coberturas":[{"legacy_id":13124,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Contrato fuente íntegro en descripción de S22AC-C07; conserva semántica y referencias literales, sin habilitar runtime."}],"hechos":["s22ac07_evalua_identificador_niubiz","s22ac07_identidad_no_unica_o_no_estable","s22ac07_normalizacion_o_inicio_invalido","s22ac07_envia_sin_parametro_o_con_colision","s22ac07_reutiliza_correo_compartido","s22ac07_sustituye_correo_real","s22ac07_produccion_sin_sandbox"],"paquete":{"tipo":"NUEVA","codigo":"S22AC-C07","clave":"s22ac_legacy_13124","familia":"INTEGRATIONS_WEBHOOKS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Identificador técnico Niubiz estable por cliente","descripcion":"BLOQUEAR incumplimiento del contrato funcional REG_CLIENT_NIUBIZ_UNIQUE_EMAIL_001. En cada intento de pago con Niubiz, el servidor consulta en public.lf_global_config los parámetros PAGOS/NIUBIZ_EMAIL_TEMPLATE y PAGOS/NIUBIZ_EMAIL_DOMAIN mediante scope/config_key; construye con esos valores vigentes un identificador técnico único, estable y reutilizable por cliente. Normaliza nombre y apellido a minúsculas, sin tildes ni espacios; el código es interno, persistente y único por cliente; el identificador no comienza con dígitos. Si faltan parámetros o identidad, ocurre colisión o Niubiz rechaza el identificador, bloquea el envío con error trazable, sin reutilizar un correo compartido ni inventar valores. El correo técnico no sustituye al correo real para los recibos. La aceptación por Niubiz de los caracteres de la plantilla, incluido el guion cuando corresponda, está NOT_TESTED y requiere prueba en sandbox; no habilita producción. Referencias literales del contrato fuente (no nuevas configuraciones ni autorización de implementación): {\"provider\":\"NIUBIZ\",\"client_code\":\"SHORT_STABLE_UNIQUE_INTERNAL_CLIENT_CODE\",\"normalization\":[\"LOWERCASE\",\"REMOVE_DIACRITICS\",\"REMOVE_WHITESPACE\"],\"first_character\":\"LETTER_REQUIRED\",\"uniqueness_scope\":\"CLIENT_GLOBAL\",\"reuse_same_client\":true,\"hyphen_niubiz_sandbox\":\"NOT_TESTED\",\"on_provider_rejection\":\"BLOCK_WITH_TRACEABLE_ERROR\",\"production_authorized\":false,\"technical_email_usage\":\"PROVIDER_IDENTIFIER_ONLY\",\"real_email_receipt_ref\":\"REG_CLIENT_PAYMENT_RECEIPT_REAL_EMAIL_001\",\"on_missing_or_collision\":\"BLOCK_WITH_TRACEABLE_ERROR\",\"niubiz_email_config_refs\":[{\"scope\":\"PAGOS\",\"config_key\":\"NIUBIZ_EMAIL_TEMPLATE\"},{\"scope\":\"PAGOS\",\"config_key\":\"NIUBIZ_EMAIL_DOMAIN\"}],\"on_technical_mailbox_not_existing\":\"NOT_BLOCKING_AFTER_PROVIDER_ACCEPTANCE\"}. Los estados pendientes y restricciones de producción se conservan; binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/13124","solicitante":"Cristhian / Claude S22-AC 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22ac07_evalua_identificador_niubiz"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22ac07_identidad_no_unica_o_no_estable"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22ac07_normalizacion_o_inicio_invalido"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ac07_envia_sin_parametro_o_con_colision"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ac07_reutiliza_correo_compartido"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ac07_sustituye_correo_real"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ac07_produccion_sin_sandbox"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22ac07_evalua_identificador_niubiz":true,"s22ac07_identidad_no_unica_o_no_estable":false,"s22ac07_normalizacion_o_inicio_invalido":false,"s22ac07_envia_sin_parametro_o_con_colision":false,"s22ac07_reutiliza_correo_compartido":false,"s22ac07_sustituye_correo_real":false,"s22ac07_produccion_sin_sandbox":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22ac07_evalua_identificador_niubiz":true,"s22ac07_identidad_no_unica_o_no_estable":true,"s22ac07_normalizacion_o_inicio_invalido":false,"s22ac07_envia_sin_parametro_o_con_colision":false,"s22ac07_reutiliza_correo_compartido":false,"s22ac07_sustituye_correo_real":false,"s22ac07_produccion_sin_sandbox":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ac07_evalua_identificador_niubiz":true,"s22ac07_identidad_no_unica_o_no_estable":false,"s22ac07_normalizacion_o_inicio_invalido":true,"s22ac07_envia_sin_parametro_o_con_colision":false,"s22ac07_reutiliza_correo_compartido":false,"s22ac07_sustituye_correo_real":false,"s22ac07_produccion_sin_sandbox":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ac07_evalua_identificador_niubiz":true,"s22ac07_identidad_no_unica_o_no_estable":false,"s22ac07_normalizacion_o_inicio_invalido":false,"s22ac07_envia_sin_parametro_o_con_colision":true,"s22ac07_reutiliza_correo_compartido":false,"s22ac07_sustituye_correo_real":false,"s22ac07_produccion_sin_sandbox":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ac07_evalua_identificador_niubiz":true,"s22ac07_identidad_no_unica_o_no_estable":false,"s22ac07_normalizacion_o_inicio_invalido":false,"s22ac07_envia_sin_parametro_o_con_colision":false,"s22ac07_reutiliza_correo_compartido":true,"s22ac07_sustituye_correo_real":false,"s22ac07_produccion_sin_sandbox":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ac07_evalua_identificador_niubiz":true,"s22ac07_identidad_no_unica_o_no_estable":false,"s22ac07_normalizacion_o_inicio_invalido":false,"s22ac07_envia_sin_parametro_o_con_colision":false,"s22ac07_reutiliza_correo_compartido":false,"s22ac07_sustituye_correo_real":true,"s22ac07_produccion_sin_sandbox":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ac07_evalua_identificador_niubiz":true,"s22ac07_identidad_no_unica_o_no_estable":false,"s22ac07_normalizacion_o_inicio_invalido":false,"s22ac07_envia_sin_parametro_o_con_colision":false,"s22ac07_reutiliza_correo_compartido":false,"s22ac07_sustituye_correo_real":false,"s22ac07_produccion_sin_sandbox":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22ac07_evalua_identificador_niubiz":false,"s22ac07_identidad_no_unica_o_no_estable":true,"s22ac07_normalizacion_o_inicio_invalido":true,"s22ac07_envia_sin_parametro_o_con_colision":true,"s22ac07_reutiliza_correo_compartido":true,"s22ac07_sustituye_correo_real":true,"s22ac07_produccion_sin_sandbox":true},"esperado":false}]},"hash":"f58223a9d8592af0ac490cdbf9217dbca9d75657fd09e62d19532ff5235a04ff","hash_paquete":"f496070c846da18e8f7416732f2f79ffa70937dd6cf6ef8eaa328d0da258ec74","hash_evaluado":"f58223a9d8","hash_paquete_10":"f496070c84","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}},{"codigo":"S22AC-C08","legacy_id":13128,"legacy_ids":[13128],"relacionadas":[],"residual":"","coberturas":[{"legacy_id":13128,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Contrato fuente íntegro en descripción de S22AC-C08; conserva semántica y referencias literales, sin habilitar runtime."}],"hechos":["s22ac08_evalua_rebote_niubiz","s22ac08_rebote_confirma_o_rechaza_pago","s22ac08_rechazo_formato_no_bloquea","s22ac08_modifica_recibo_real","s22ac08_identificador_no_configurado","s22ac08_produccion_sin_sandbox"],"paquete":{"tipo":"NUEVA","codigo":"S22AC-C08","clave":"s22ac_legacy_13128","familia":"INTEGRATIONS_WEBHOOKS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Rebote técnico Niubiz informativo sin efecto de pago","descripcion":"BLOQUEAR incumplimiento del contrato funcional REG_CLIENT_NIUBIZ_GENERIC_BOUNCE_001. El identificador técnico usado para Niubiz se deriva de public.lf_global_config mediante scope PAGOS y config_key NIUBIZ_EMAIL_TEMPLATE y NIUBIZ_EMAIL_DOMAIN; no necesita corresponder a un buzón existente. Si Niubiz admite el identificador y luego ocurre un rebote, LF lo acepta como evento informativo registrado en el reporte operativo del proveedor. El rebote por sí solo no confirma ni rechaza un pago ni modifica el envío del recibo al correo real. Si Niubiz rechaza el identificador por validación de formulario o API, es error trazable y bloquea el intento; nunca se fabrica PAYMENT_CONFIRMED. La aceptación de los caracteres de la plantilla vigente, incluido el guion si aparece, sigue NOT_TESTED hasta verificación real en sandbox Niubiz. Referencias literales del contrato fuente (no nuevas configuraciones ni autorización de implementación): {\"provider\":\"NIUBIZ\",\"bounce_source\":\"NIUBIZ_OPERATIONAL_REPORTS\",\"hyphen_niubiz_sandbox\":\"NOT_TESTED\",\"production_authorized\":false,\"niubiz_email_config_refs\":[{\"scope\":\"PAGOS\",\"config_key\":\"NIUBIZ_EMAIL_TEMPLATE\"},{\"scope\":\"PAGOS\",\"config_key\":\"NIUBIZ_EMAIL_DOMAIN\"}],\"provider_format_rejection\":\"BLOCK_AND_TRACE\",\"sandbox_expected_evidence\":\"PROVIDER_HOSTED_FORM_ACTUAL_RESULT\",\"bounce_is_payment_rejection\":false,\"generic_email_bounce_policy\":\"ACCEPT_AFTER_PROVIDER_ACCEPTANCE\",\"customer_receipt_email_source\":\"REAL_CUSTOMER_EMAIL\",\"bounce_is_payment_confirmation\":false,\"technical_email_mailbox_required\":false}. Los estados pendientes y restricciones de producción se conservan; binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/13128","solicitante":"Cristhian / Claude S22-AC 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22ac08_evalua_rebote_niubiz"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22ac08_rebote_confirma_o_rechaza_pago"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22ac08_rechazo_formato_no_bloquea"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ac08_modifica_recibo_real"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ac08_identificador_no_configurado"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22ac08_produccion_sin_sandbox"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22ac08_evalua_rebote_niubiz":true,"s22ac08_rebote_confirma_o_rechaza_pago":false,"s22ac08_rechazo_formato_no_bloquea":false,"s22ac08_modifica_recibo_real":false,"s22ac08_identificador_no_configurado":false,"s22ac08_produccion_sin_sandbox":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22ac08_evalua_rebote_niubiz":true,"s22ac08_rebote_confirma_o_rechaza_pago":true,"s22ac08_rechazo_formato_no_bloquea":false,"s22ac08_modifica_recibo_real":false,"s22ac08_identificador_no_configurado":false,"s22ac08_produccion_sin_sandbox":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ac08_evalua_rebote_niubiz":true,"s22ac08_rebote_confirma_o_rechaza_pago":false,"s22ac08_rechazo_formato_no_bloquea":true,"s22ac08_modifica_recibo_real":false,"s22ac08_identificador_no_configurado":false,"s22ac08_produccion_sin_sandbox":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ac08_evalua_rebote_niubiz":true,"s22ac08_rebote_confirma_o_rechaza_pago":false,"s22ac08_rechazo_formato_no_bloquea":false,"s22ac08_modifica_recibo_real":true,"s22ac08_identificador_no_configurado":false,"s22ac08_produccion_sin_sandbox":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ac08_evalua_rebote_niubiz":true,"s22ac08_rebote_confirma_o_rechaza_pago":false,"s22ac08_rechazo_formato_no_bloquea":false,"s22ac08_modifica_recibo_real":false,"s22ac08_identificador_no_configurado":true,"s22ac08_produccion_sin_sandbox":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22ac08_evalua_rebote_niubiz":true,"s22ac08_rebote_confirma_o_rechaza_pago":false,"s22ac08_rechazo_formato_no_bloquea":false,"s22ac08_modifica_recibo_real":false,"s22ac08_identificador_no_configurado":false,"s22ac08_produccion_sin_sandbox":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22ac08_evalua_rebote_niubiz":false,"s22ac08_rebote_confirma_o_rechaza_pago":true,"s22ac08_rechazo_formato_no_bloquea":true,"s22ac08_modifica_recibo_real":true,"s22ac08_identificador_no_configurado":true,"s22ac08_produccion_sin_sandbox":true},"esperado":false}]},"hash":"101bde119de140dd9b5b97dc57ce62841ecaa6623e21eb8717dae487b3301369","hash_paquete":"1135f855b077724f98876902e634efb7ce9e174d475e3725d9535b111f91eabb","hash_evaluado":"101bde119d","hash_paquete_10":"1135f855b0","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude 2026-11-25 20:40 Lima: evaluador independiente 55/55, descripción y valor_config comparados con referencias literales');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22AC_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22AC_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22AC_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22AC_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22AC_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 VALUES(lid,cd,1,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-25 20:40 Lima'),h,'GPT / Claude S22-AC independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22AC_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>(SELECT coalesce(sum(jsonb_array_length(value->'coberturas')),0) FROM jsonb_array_elements(packs)) OR after_replaced<>before_replaced+expected_delta) THEN RAISE EXCEPTION 'S22AC_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22AC_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22AC_PASS JUICIOS=% AUTO=% VECTORES=% links=% replaced=% DPIG03=0',n,n,vectors,links,after_replaced;
END $s22$;
COMMIT;
